import {T,scene,mesh,box,mat} from './visuals3.js';
export const forestRoute=[{x:0,z:27},{x:7,z:18},{x:3,z:12},{x:3,z:3},{x:-6,z:-2},{x:-3,z:-8},{x:-3,z:-17},{x:6,z:-22},{x:0,z:-29}];
export const rivers=[{z:7,x:3,width:1.9},{z:-12,x:-3,width:1.6}];
export function trailDistance(x,z){let best=100;for(let i=1;i<forestRoute.length;i++){let a=forestRoute[i-1],b=forestRoute[i],dx=b.x-a.x,dz=b.z-a.z,t=Math.max(0,Math.min(1,((x-a.x)*dx+(z-a.z)*dz)/(dx*dx+dz*dz)));best=Math.min(best,Math.hypot(x-a.x-dx*t,z-a.z-dz*t))}return best}
export function buildForest(){const root=new T.Group();scene.add(root);let seed=319;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};let blockers=[];
box(0,-.28,0,38,.5,68,'#253e32',root);for(let i=1;i<forestRoute.length;i++){let a=forestRoute[i-1],b=forestRoute[i],len=Math.hypot(a.x-b.x,a.z-b.z);for(let j=0;j<len;j+=.75){let t=j/len,z=a.z+(b.z-a.z)*t;if(rivers.some(r=>Math.abs(z-r.z)<2.4))continue;let p=mesh(new T.CylinderGeometry(1.15+rand()*.2,1.3,.025,9),'#655e47',a.x+(b.x-a.x)*t,-.01,z,root);p.rotation.y=rand()*6}}
const trees=[],bushes=[],grasses=[];for(let z=-32;z<=32;z+=2)for(let x=-17;x<=17;x+=2){let px=x+(rand()-.5)*1.3,pz=z+(rand()-.5)*1.3,d=trailDistance(px,pz);if(rivers.some(r=>Math.abs(pz-r.z)<2.6))continue;if(d>2.1&&rand()>.14){let h=3.5+rand()*3.2,s=.7+rand()*.6;trees.push({x:px,z:pz,h,s});blockers.push({x:px,z:pz,w:.65*s,d:.65*s})}else if(d>1.25&&d<4){bushes.push({x:px,z:pz,s:.4+rand()*.5})}for(let j=0;j<3;j++)if(d>1.15)grasses.push({x:px+(rand()-.5),z:pz+(rand()-.5),s:.2+rand()*.35})}
function instances(geo,color,items,transform){let m=new T.InstancedMesh(geo,mat(color),items.length),dummy=new T.Object3D();items.forEach((o,i)=>{dummy.position.set(o.x,0,o.z);dummy.rotation.set(0,0,0);dummy.scale.set(1,1,1);transform(dummy,o,i);dummy.updateMatrix();m.setMatrixAt(i,dummy.matrix)});m.receiveShadow=true;root.add(m);return m}
instances(new T.CylinderGeometry(.2,.33,1,7),'#544c3b',trees,(d,o)=>{d.position.y=o.h*.45;d.scale.set(o.s,o.h*.9,o.s)});
let canopies=[];for(let layer=0;layer<3;layer++)canopies.push(instances(new T.ConeGeometry(1,1,7),['#294c40','#345b48','#416950'][layer],trees,(d,o)=>{d.position.y=o.h*(.6+layer*.18);let s=o.s*(1.5-layer*.26);d.scale.set(s,o.h*.48,s);d.rotation.y=o.x}));
instances(new T.IcosahedronGeometry(1,1),'#426441',bushes,(d,o)=>{d.position.y=o.s*.4;d.scale.set(o.s,o.s*.55,o.s*.8)});
instances(new T.ConeGeometry(.11,1,4),'#677b4c',grasses,(d,o)=>{d.position.y=o.s/2;d.scale.set(1,o.s,1);d.rotation.z=Math.sin(o.x)*.2});
for(let r of rivers){let water=box(0,-.08,r.z,37,.09,4.6,'#30596b',root);water.material=water.material.clone();water.material.metalness=.4;water.material.roughness=.25;for(let j=0;j<15;j++){let plank=box(r.x,.15,r.z-2.6+j*.38,r.width,.16,.31,j%4?'#9c8058':'#745c43',root);plank.rotation.z=Math.sin(j*2)*.025}for(let side of [-1,1]){for(let end of [-1,1])box(r.x+side*(r.width/2+.15),.65,r.z+end*2.65,.15,1.4,.15,'#7c6a4f',root);let rope=mesh(new T.CylinderGeometry(.035,.035,5.4,6),'#a69b79',r.x+side*(r.width/2+.15),.95,r.z,root);rope.rotation.x=Math.PI/2}for(let j=0;j<14;j++){let x=-17+j*2.6;if(Math.abs(x-r.x)<1.8)continue;let stone=mesh(new T.IcosahedronGeometry(.45+rand()*.3,0),'#606e68',x,.05,r.z+(j%2?2.5:-2.5),root);stone.scale.y=.6}}
for(let [x,z,angle]of [[5,15,.8],[-3,0,1.1],[1,-19,-.4]]){let log=mesh(new T.CylinderGeometry(.25,.32,2.2,9),'#685540',x,.28,z,root);log.rotation.z=Math.PI/2;log.rotation.y=angle;blockers.push({x,z,w:1.6,d:.65});for(let i=0;i<3;i++)mesh(new T.IcosahedronGeometry(.11,0),'#b59e79',x+i*.18,.55,z,root)}
for(let x of [-18.5,18.5])blockers.push({x,z:0,w:.5,d:67});for(let z of [-33.5,33.5])blockers.push({x:0,z,w:37,d:.5});
function updateView(hero,cam){let vx=cam.x-hero.x,vz=cam.z-hero.z,len=vx*vx+vz*vz,dummy=new T.Object3D();trees.forEach((o,i)=>{let t=((o.x-hero.x)*vx+(o.z-hero.z)*vz)/len,perp=Math.hypot(o.x-hero.x-vx*t,o.z-hero.z-vz*t),hide=t>-.12&&t<1.15&&perp<3.1;for(let layer=0;layer<3;layer++){dummy.position.set(o.x,o.h*(.6+layer*.18),o.z);dummy.rotation.set(0,o.x,0);let s=o.s*(1.5-layer*.26);dummy.scale.set(s,o.h*.48,s);if(hide)dummy.scale.multiplyScalar(.001);dummy.updateMatrix();canopies[layer].setMatrixAt(i,dummy.matrix)}});canopies.forEach(m=>m.instanceMatrix.needsUpdate=true)}
return{root,blockers,treeCount:trees.length,bridges:rivers,updateView};}
export function inRiver(p){return rivers.some(r=>Math.abs(p.z-r.z)<2.3&&Math.abs(p.x-r.x)>r.width/2-.25)}
